@block F16Trail begin
    # Scene helper (no physics, generated by design/build_model.py): the dots of a flight-path
    # trail, 12 past positions of an aircraft 0.08 s apart, relative to the reference aircraft
    # of the view (see F16View) plus a formation offset. Every tick stores the position in a
    # shift register r1..r13; between ticks dot k interpolates linearly between the stored
    # samples around t - k*Ts, so the dots glide along the path instead of hopping. Until the
    # register has filled, a dot sits on the aircraft.
    @inputs begin
        g::Vec{7}, [description = "Pose of the aircraft (qw, qx, qy, qz, x, y, z)"]
        g0::Vec{7}, [description = "Pose of the reference aircraft of the view"]
    end
    @outputs begin
        d1::Vec{7}, [description = "Pose of dot 1 (0.08 s back)"]
        d2::Vec{7}, [description = "Pose of dot 2 (0.16 s back)"]
        d3::Vec{7}, [description = "Pose of dot 3 (0.24 s back)"]
        d4::Vec{7}, [description = "Pose of dot 4 (0.32 s back)"]
        d5::Vec{7}, [description = "Pose of dot 5 (0.4 s back)"]
        d6::Vec{7}, [description = "Pose of dot 6 (0.48 s back)"]
        d7::Vec{7}, [description = "Pose of dot 7 (0.56 s back)"]
        d8::Vec{7}, [description = "Pose of dot 8 (0.64 s back)"]
        d9::Vec{7}, [description = "Pose of dot 9 (0.72 s back)"]
        d10::Vec{7}, [description = "Pose of dot 10 (0.8 s back)"]
        d11::Vec{7}, [description = "Pose of dot 11 (0.88 s back)"]
        d12::Vec{7}, [description = "Pose of dot 12 (0.96 s back)"]
    end
    @parameters begin
        dx::Real = 0.0, [unit = "m", description = "Formation offset, x"]
        dy::Real = 0.0, [unit = "m", description = "Formation offset, y"]
        dz::Real = 0.0, [unit = "m", description = "Formation offset, z"]
    end
    @variables begin
        r1x::Real = 0.0, [unit = "m"]
        r1y::Real = 0.0, [unit = "m"]
        r1z::Real = 0.0, [unit = "m"]
        r2x::Real = 0.0, [unit = "m"]
        r2y::Real = 0.0, [unit = "m"]
        r2z::Real = 0.0, [unit = "m"]
        r3x::Real = 0.0, [unit = "m"]
        r3y::Real = 0.0, [unit = "m"]
        r3z::Real = 0.0, [unit = "m"]
        r4x::Real = 0.0, [unit = "m"]
        r4y::Real = 0.0, [unit = "m"]
        r4z::Real = 0.0, [unit = "m"]
        r5x::Real = 0.0, [unit = "m"]
        r5y::Real = 0.0, [unit = "m"]
        r5z::Real = 0.0, [unit = "m"]
        r6x::Real = 0.0, [unit = "m"]
        r6y::Real = 0.0, [unit = "m"]
        r6z::Real = 0.0, [unit = "m"]
        r7x::Real = 0.0, [unit = "m"]
        r7y::Real = 0.0, [unit = "m"]
        r7z::Real = 0.0, [unit = "m"]
        r8x::Real = 0.0, [unit = "m"]
        r8y::Real = 0.0, [unit = "m"]
        r8z::Real = 0.0, [unit = "m"]
        r9x::Real = 0.0, [unit = "m"]
        r9y::Real = 0.0, [unit = "m"]
        r9z::Real = 0.0, [unit = "m"]
        r10x::Real = 0.0, [unit = "m"]
        r10y::Real = 0.0, [unit = "m"]
        r10z::Real = 0.0, [unit = "m"]
        r11x::Real = 0.0, [unit = "m"]
        r11y::Real = 0.0, [unit = "m"]
        r11z::Real = 0.0, [unit = "m"]
        r12x::Real = 0.0, [unit = "m"]
        r12y::Real = 0.0, [unit = "m"]
        r12z::Real = 0.0, [unit = "m"]
        r13x::Real = 0.0, [unit = "m"]
        r13y::Real = 0.0, [unit = "m"]
        r13z::Real = 0.0, [unit = "m"]
        nfill::Real = 0.0, [description = "Samples stored so far"]
        tk::Real = 0.0, [unit = "s", description = "Time of the last tick"]
        frac::Real = 0.0, [description = "(t - tk)/Ts"]
    end
    @discrete Ts = 0.08 begin
        r13x = r12x
        r13y = r12y
        r13z = r12z
        r12x = r11x
        r12y = r11y
        r12z = r11z
        r11x = r10x
        r11y = r10y
        r11z = r10z
        r10x = r9x
        r10y = r9y
        r10z = r9z
        r9x = r8x
        r9y = r8y
        r9z = r8z
        r8x = r7x
        r8y = r7y
        r8z = r7z
        r7x = r6x
        r7y = r6y
        r7z = r6z
        r6x = r5x
        r6y = r5y
        r6z = r5z
        r5x = r4x
        r5y = r4y
        r5z = r4z
        r4x = r3x
        r4y = r3y
        r4z = r3z
        r3x = r2x
        r3y = r2y
        r3z = r2z
        r2x = r1x
        r2y = r1y
        r2z = r1z
        r1x = g[5]
        r1y = g[6]
        r1z = g[7]
        nfill = min(nfill + 1.0, 13.0)
        tk = t
    end
    @equations begin
        frac ~ (t - tk) / 0.08
        d1[1] ~ 1.0
        d1[2] ~ 0.0
        d1[3] ~ 0.0
        d1[4] ~ 0.0
        d1[5] ~ ifelse(nfill > 1.5, r2x + frac * (r1x - r2x), g[5]) - g0[5] + dx
        d1[6] ~ ifelse(nfill > 1.5, r2y + frac * (r1y - r2y), g[6]) - g0[6] + dy
        d1[7] ~ ifelse(nfill > 1.5, r2z + frac * (r1z - r2z), g[7]) - g0[7] + dz
        d2[1] ~ 1.0
        d2[2] ~ 0.0
        d2[3] ~ 0.0
        d2[4] ~ 0.0
        d2[5] ~ ifelse(nfill > 2.5, r3x + frac * (r2x - r3x), g[5]) - g0[5] + dx
        d2[6] ~ ifelse(nfill > 2.5, r3y + frac * (r2y - r3y), g[6]) - g0[6] + dy
        d2[7] ~ ifelse(nfill > 2.5, r3z + frac * (r2z - r3z), g[7]) - g0[7] + dz
        d3[1] ~ 1.0
        d3[2] ~ 0.0
        d3[3] ~ 0.0
        d3[4] ~ 0.0
        d3[5] ~ ifelse(nfill > 3.5, r4x + frac * (r3x - r4x), g[5]) - g0[5] + dx
        d3[6] ~ ifelse(nfill > 3.5, r4y + frac * (r3y - r4y), g[6]) - g0[6] + dy
        d3[7] ~ ifelse(nfill > 3.5, r4z + frac * (r3z - r4z), g[7]) - g0[7] + dz
        d4[1] ~ 1.0
        d4[2] ~ 0.0
        d4[3] ~ 0.0
        d4[4] ~ 0.0
        d4[5] ~ ifelse(nfill > 4.5, r5x + frac * (r4x - r5x), g[5]) - g0[5] + dx
        d4[6] ~ ifelse(nfill > 4.5, r5y + frac * (r4y - r5y), g[6]) - g0[6] + dy
        d4[7] ~ ifelse(nfill > 4.5, r5z + frac * (r4z - r5z), g[7]) - g0[7] + dz
        d5[1] ~ 1.0
        d5[2] ~ 0.0
        d5[3] ~ 0.0
        d5[4] ~ 0.0
        d5[5] ~ ifelse(nfill > 5.5, r6x + frac * (r5x - r6x), g[5]) - g0[5] + dx
        d5[6] ~ ifelse(nfill > 5.5, r6y + frac * (r5y - r6y), g[6]) - g0[6] + dy
        d5[7] ~ ifelse(nfill > 5.5, r6z + frac * (r5z - r6z), g[7]) - g0[7] + dz
        d6[1] ~ 1.0
        d6[2] ~ 0.0
        d6[3] ~ 0.0
        d6[4] ~ 0.0
        d6[5] ~ ifelse(nfill > 6.5, r7x + frac * (r6x - r7x), g[5]) - g0[5] + dx
        d6[6] ~ ifelse(nfill > 6.5, r7y + frac * (r6y - r7y), g[6]) - g0[6] + dy
        d6[7] ~ ifelse(nfill > 6.5, r7z + frac * (r6z - r7z), g[7]) - g0[7] + dz
        d7[1] ~ 1.0
        d7[2] ~ 0.0
        d7[3] ~ 0.0
        d7[4] ~ 0.0
        d7[5] ~ ifelse(nfill > 7.5, r8x + frac * (r7x - r8x), g[5]) - g0[5] + dx
        d7[6] ~ ifelse(nfill > 7.5, r8y + frac * (r7y - r8y), g[6]) - g0[6] + dy
        d7[7] ~ ifelse(nfill > 7.5, r8z + frac * (r7z - r8z), g[7]) - g0[7] + dz
        d8[1] ~ 1.0
        d8[2] ~ 0.0
        d8[3] ~ 0.0
        d8[4] ~ 0.0
        d8[5] ~ ifelse(nfill > 8.5, r9x + frac * (r8x - r9x), g[5]) - g0[5] + dx
        d8[6] ~ ifelse(nfill > 8.5, r9y + frac * (r8y - r9y), g[6]) - g0[6] + dy
        d8[7] ~ ifelse(nfill > 8.5, r9z + frac * (r8z - r9z), g[7]) - g0[7] + dz
        d9[1] ~ 1.0
        d9[2] ~ 0.0
        d9[3] ~ 0.0
        d9[4] ~ 0.0
        d9[5] ~ ifelse(nfill > 9.5, r10x + frac * (r9x - r10x), g[5]) - g0[5] + dx
        d9[6] ~ ifelse(nfill > 9.5, r10y + frac * (r9y - r10y), g[6]) - g0[6] + dy
        d9[7] ~ ifelse(nfill > 9.5, r10z + frac * (r9z - r10z), g[7]) - g0[7] + dz
        d10[1] ~ 1.0
        d10[2] ~ 0.0
        d10[3] ~ 0.0
        d10[4] ~ 0.0
        d10[5] ~ ifelse(nfill > 10.5, r11x + frac * (r10x - r11x), g[5]) - g0[5] + dx
        d10[6] ~ ifelse(nfill > 10.5, r11y + frac * (r10y - r11y), g[6]) - g0[6] + dy
        d10[7] ~ ifelse(nfill > 10.5, r11z + frac * (r10z - r11z), g[7]) - g0[7] + dz
        d11[1] ~ 1.0
        d11[2] ~ 0.0
        d11[3] ~ 0.0
        d11[4] ~ 0.0
        d11[5] ~ ifelse(nfill > 11.5, r12x + frac * (r11x - r12x), g[5]) - g0[5] + dx
        d11[6] ~ ifelse(nfill > 11.5, r12y + frac * (r11y - r12y), g[6]) - g0[6] + dy
        d11[7] ~ ifelse(nfill > 11.5, r12z + frac * (r11z - r12z), g[7]) - g0[7] + dz
        d12[1] ~ 1.0
        d12[2] ~ 0.0
        d12[3] ~ 0.0
        d12[4] ~ 0.0
        d12[5] ~ ifelse(nfill > 12.5, r13x + frac * (r12x - r13x), g[5]) - g0[5] + dx
        d12[6] ~ ifelse(nfill > 12.5, r13y + frac * (r12y - r13y), g[6]) - g0[6] + dy
        d12[7] ~ ifelse(nfill > 12.5, r13z + frac * (r12z - r13z), g[7]) - g0[7] + dz
    end
end
